use super::*;
use semio_framework_trace::observe_heap_allocations_on_this_thread;
fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:16*1024*1024,maximum_release_bytes:16*1024*1024,maximum_depth:64}}
#[test]
fn native_transition_identity_fields_are_bounded_and_cancel_every_original_prefix(){let law:serde_json::Value=serde_json::from_str(include_str!("ids.json")).unwrap();for case in law["cases"].as_array().unwrap(){for width in law["widths"].as_array().unwrap(){for cut in [0,1,2,3,8,64,usize::MAX]{let prefix="x".repeat(width.as_u64().unwrap()as usize);let source=format!("{prefix}{}",case["source"].as_str().unwrap());let expected=format!("{prefix}{}",case["expected"].as_str().unwrap());let suffix=case["suffix"].as_u64().map(|v|v as usize);let mut owner=OriginalTransitionIds::default();let mut born=0;let mut freed=0;for turn in 0..10000{if turn==cut||owner.complete()==1{break}let d=owner.demands(&source,suffix,1).unwrap();for denied in [RetainedCloneGrant{maximum_items:0,..grant()},RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.saturating_sub(1),..grant()},RetainedCloneGrant{maximum_depth:0,..grant()}]{if !semio_framework_value::retained_clone::retained_clone_grant_admits(denied,d){let(p,h)=observe_heap_allocations_on_this_thread(||owner.advance(&source,suffix,1,denied).unwrap());assert_eq!(p,Default::default());assert_eq!((h.requested_bytes,h.released_bytes),(0,0));}}let(p,h)=observe_heap_allocations_on_this_thread(||owner.advance(&source,suffix,1,grant()).unwrap());assert!(p.fits(grant()));assert_eq!((h.requested_bytes,h.released_bytes),(p.retained_capacity_bytes,p.released_bytes));born+=h.requested_bytes;freed+=h.released_bytes;}if owner.complete()==1{assert_eq!(owner.values()[0].0,expected);}for _ in 0..10000{if owner.terminal_is_empty(){break}let d=owner.close_demands(4096).unwrap();let g=RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.max(4096),..grant()};let(p,h)=observe_heap_allocations_on_this_thread(||owner.close_step(g).unwrap().progress());assert_eq!((h.requested_bytes,h.released_bytes),(p.retained_capacity_bytes,p.released_bytes));born+=h.requested_bytes;freed+=h.released_bytes;}assert!(owner.terminal_is_empty());assert_eq!(born,freed);}}}}
